if (gw.type == GUILD_WAR_TYPE_FIELD)
{
	// MT2009_PLUS_GUILD_WAR_JOIN_V1 (field): a field war has no war map. A war on a bot guild
	// is fought on the kingdom's guild map, and joining takes the player
	// to its guild's camp there (EnterPlayerBotFieldWar); any other field
	// war is told it is fought wherever the guilds meet.
	if (gw.state == GUILD_WAR_ON_WAR)
		CPlayerBotManager::instance().OnPlayerFieldWarEntry(ch, GetID(), dwOppGID);
	else
		ch->ChatPacket(CHAT_TYPE_INFO, LC_TEXT("The war is already over."));
	return;
}

if (gw.state != GUILD_WAR_ON_WAR)

// MT2009_PLUS_GUILD_WAR_JOIN_V1 (command): the client's "Wejdz na wojne" button (the guild
// war board and the notice at the war's start, uiguild.py / game.py). The
// same entry as the guild_war_join letter's "Tak": the war map of an arena
// war, the guild's camp on the kingdom's guild map in a war on a bot guild.
ACMD(do_guild_war_enter)
{
	CGuild* g = ch->GetGuild();
	if (!g)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "[Wojna] Nie nalezysz do gildii.");
		return;
	}
	const DWORD dwOppGID = g->UnderAnyWar();
	if (!dwOppGID)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "[Wojna] Twoja gildia nie prowadzi teraz wojny.");
		return;
	}
	if (ch->GetWarMap())
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "[Wojna] Jestes juz na polu wojny.");
		return;
	}
	if (ch->IsDead() || !ch->CanWarp())
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "[Wojna] Teraz nie mozesz sie przeniesc - sprobuj za chwile.");
		return;
	}
	g->GuildWarEntryAccept(dwOppGID, ch);
}

ACMD(do_war)
{

// MT2009_PLUS_GUILD_WAR_OBSERVE_V1 (list): a field war has no war map - but the bots'
// arena war is a field war with its own copy of the arena, and the Battle
// Executor lists it (playerbot_guild_war.h).
if (g->GetGuildWarType(g2) == GUILD_WAR_TYPE_FIELD && !CPlayerBotManager::instance().IsPlayerBotArenaWar(g1, g2))
	return;

PIXEL_POSITION pos;

// MT2009_PLUS_GUILD_WAR_OBSERVE_V1 (watch): an onlooker of the bots' arena war goes to
// its copy of the arena (playerbot_guild_war.h), not to a war map it has none of.
{
	long lArena = 0, lX = 0, lY = 0;
	if (g1->GetGuildWarType(gid2) == GUILD_WAR_TYPE_FIELD &&
			CPlayerBotManager::instance().GetPlayerBotArenaObserverPos(gid1, gid2, lArena, lX, lY))
	{
		LPCHARACTER chWatch = CQuestManager::instance().GetCurrentCharacterPtr();
		if (!chWatch || chWatch->IsHack())
			return 0;
		chWatch->SetQuestFlag("war.is_war_member", 0);
		chWatch->SaveExitLocation();
		chWatch->WarpSet(lX, lY, lArena);
		return 0;
	}
}

DWORD dwMapIndex = g1->GetGuildWarMapIndex(gid2);
